public class StringUtils {
    /** 
     * Gets a substring from the specified String avoiding exceptions. 
     */
    public static String sub(String str, int start, int end) {
        if (str == null) {
            return null;
        }
        int len = str.length();
        if (start < 0) {
            start = 0;
        }
        if (end > len) {
            end = len;
        }
        if (start > end) {
            return "";
        }
        return str.substring(start, end);
    }

    public static void main(String[] args) {
        System.out.println(sub("Hello, World!", 7, 12)); // Output: World
        System.out.println(sub("Hello, World!", 0, 5));  // Output: Hello
        System.out.println(sub("Hello, World!", -1, 5)); // Output: Hello
        System.out.println(sub("Hello, World!", 7, 20)); // Output: World!
        System.out.println(sub("Hello, World!", 12, 7)); // Output: (empty string)
        System.out.println(sub(null, 0, 5));            // Output: null
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[32];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        int requiredLength = this.length + byteLength;
        if (requiredLength > data.length) {
            enlarge(requiredLength - data.length);
        }

        if (byteArrayValue == null) {
            Arrays.fill(data, this.length, this.length + byteLength, (byte) 0);
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, this.length, byteLength);
        }

        this.length = requiredLength;
        return this;
    }

    private void enlarge(final int size) {
        int newSize = Math.max(data.length << 1, data.length + size);
        data = Arrays.copyOf(data, newSize);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putByteArray(new byte[]{1, 2, 3, 4}, 1, 2);
        System.out.println(Arrays.toString(bv.data));
    }
}

