import java.util.Properties;

public class PropertyFinder {
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        return substituteVars(value, props);
    }

    private static String substituteVars(String value, Properties props) {
        StringBuilder result = new StringBuilder();
        int varStart = -1;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '$' && i + 1 < value.length() && value.charAt(i + 1) == '{') {
                if (varStart == -1) {
                    varStart = i;
                }
            } else if (varStart != -1 && c == '}') {
                String varName = value.substring(varStart + 2, i);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    result.append(value, varStart, i + 1).append(varValue);
                } else {
                    result.append(value, varStart, i + 1);
                }
                varStart = -1;
            } else if (varStart == -1) {
                result.append(c);
            }
        }
        if (varStart != -1) {
            result.append(value.substring(varStart));
        }
        return result.toString();
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");
        System.out.println(findAndSubst("greeting", props)); // Output: Hello, World!
    }
}

