public class UnescapeJava {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        StringBuilder output = new StringBuilder();
        int length = str.length();
        for (int i = 0; i < length; i++) {
            char currentChar = str.charAt(i);
            if (currentChar == '\\') {
                if (i + 1 < length) {
                    char nextChar = str.charAt(i + 1);
                    switch (nextChar) {
                        case 'b':
                            output.append('\b');
                            i++;
                            break;
                        case 't':
                            output.append('\t');
                            i++;
                            break;
                        case 'n':
                            output.append('\n');
                            i++;
                            break;
                        case 'f':
                            output.append('\f');
                            i++;
                            break;
                        case 'r':
                            output.append('\r');
                            i++;
                            break;
                        case '\"':
                            output.append('\"');
                            i++;
                            break;
                        case '\'':
                            output.append('\'');
                            i++;
                            break;
                        case '\\':
                            output.append('\\');
                            i++;
                            break;
                        case 'u':
                            if (i + 5 < length) {
                                String hex = str.substring(i + 2, i + 6);
                                output.append((char) Integer.parseInt(hex, 16));
                                i += 5;
                            } else {
                                throw new Exception("Invalid Unicode sequence");
                            }
                            break;
                        default:
                            output.append(currentChar);
                            break;
                    }
                } else {
                    output.append(currentChar);
                }
            } else {
                output.append(currentChar);
            }
        }
        return output.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(unescapeJava("This is a test string with a newline:\\nand a tab:\\t"));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.nio.charset.Charset;
