private static String javaCharset(String charset) {
    if (charset == null) {
        return null;
    }

    // Map of MIME charset names to Java charset names
    Map<String, String> mimeToJavaCharsetMap = new HashMap<>();
    mimeToJavaCharsetMap.put("iso-8859-1", StandardCharsets.ISO_8859_1.name());
    mimeToJavaCharsetMap.put("utf-8", StandardCharsets.UTF_8.name());
    mimeToJavaCharsetMap.put("utf-16", StandardCharsets.UTF_16.name());
    mimeToJavaCharsetMap.put("utf-16be", StandardCharsets.UTF_16BE.name());
    mimeToJavaCharsetMap.put("utf-16le", StandardCharsets.UTF_16LE.name());
    mimeToJavaCharsetMap.put("us-ascii", StandardCharsets.US_ASCII.name());

    // Check if the charset is a standard one
    if (mimeToJavaCharsetMap.containsKey(charset.toLowerCase())) {
        return mimeToJavaCharsetMap.get(charset.toLowerCase());
    }

    // Try to find the charset using Java's Charset class
    try {
        return Charset.forName(charset).name();
    } catch (IllegalArgumentException e) {
        return null; // Return null if the charset is not found
    }
}

