public class CategoryTree {
    private Category root;

    public CategoryTree(Category root) {
        this.root = root;
    }

    protected int removeUnusedNodes() {
        return removeUnusedNodesHelper(root);
    }

    private int removeUnusedNodesHelper(Category node) {
        int removedCount = 0;
        List<Category> activeChildren = new ArrayList<>();

        for (Category child : node.getChildren()) {
            if (child.isActive()) {
                activeChildren.add(child);
                removedCount += removeUnusedNodesHelper(child);
            } else {
                removedCount++;
            }
        }

        node.getChildren().clear();
        node.getChildren().addAll(activeChildren);

        return removedCount;
    }

    public static void main(String[] args) {
        Category root = new Category("Root", true);
        Category child1 = new Category("Child1", false);
        Category child2 = new Category("Child2", true);
        Category child3 = new Category("Child3", false);
        Category child4 = new Category("Child4", true);

        root.addChild(child1);
        root.addChild(child2);
        root.addChild(child3);
        root.addChild(child4);

        CategoryTree tree = new CategoryTree(root);
        int removed = tree.removeUnusedNodes();
        System.out.println("Removed nodes: " + removed);
