import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[32];
        this.length = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        if (byteArrayValue == null) {
            enlarge(byteLength);
            Arrays.fill(data, length, length + byteLength, (byte) 0);
            length += byteLength;
            return this;
        }

        int requiredLength = length + byteLength;
        if (requiredLength > data.length) {
            enlarge(requiredLength - length);
        }

        System.arraycopy(byteArrayValue, byteOffset, data, length, byteLength);
        length = requiredLength;
        return this;
    }

    private void enlarge(int increment) {
        int newLength = Math.max(data.length << 1, data.length + increment);
        data = Arrays.copyOf(data, newLength);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putByteArray(new byte[]{1, 2, 3, 4, 5}, 1, 3);
        System.out.println(Arrays.toString(bv.data));
    }
}

