        ListNodeImpl<E> prev = node.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            node.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            node.next = null;
        }

        node.item = null;
        size--;
        return true;
    }

    public static void main(String[] args) {
        LinkedListImpl<String> list = new LinkedListImpl<>();
        ListNodeImpl<String> node1 = new ListNodeImpl<>(null, "first", null);
        ListNodeImpl<String> node2 = new ListNodeImpl<>(node1, "second", null);
        node1.next = node2;
        list.first = node1;
        list.last = node2;
        list.size = 2;

        list.unlink(node2);
        System.out.println(list.size); // Should print 1
    }
}

