public class TokenParser {
    private int pos;
    private int len;
    private boolean lowerCaseNames;
    private int i1;
    private int i2;
    private char[] chars;

    public TokenParser(char[] inputChars) {
        this.chars = inputChars;
        this.pos = 0;
        this.len = chars.length;
    }

    private boolean hasChar() {
        return pos < len;
    }

    private void setLowerCaseNames(boolean lowerCaseNames) {
        this.lowerCaseNames = lowerCaseNames;
    }

    private String getToken(boolean lowerCase) {
        String token = new String(chars, i1, i2 - i1);
        return lowerCase ? token.toLowerCase() : token;
    }

    private boolean isOneOf(char ch, char[] terminators) {
        for (char terminator : terminators) {
            if (ch == terminator) {
                return true;
            }
        }
        return false;
    }

    private String parseToken(final char[] terminators) {
        char loc0;
        i1 = pos;
        i2 = pos;
        while (hasChar()) {
            loc0 = chars[pos];
            if (isOneOf(loc0, terminators)) {
                break;
            }
            i2++;
            pos++;
        }
        return getToken(false);
    }

    public static void main(String[] args) {
        char[] input = "exampleToken,anotherToken".toCharArray();
        TokenParser parser = new TokenParser(input);
        char[] terminators = {','};
        System.out.println(parser.parseToken(terminators)); // Output: exampleToken
    }
}

