public class ByteVector {
    private byte[] data;
    private int length;

    public ByteVector() {
        this.data = new byte[10];
        this.length = 0;
    }

    public ByteVector putInt(final int intValue) {
        int loc0 = this.length;
        if (loc0 + 4 > data.length) {
            enlarge(4);
        }
        byte[] loc1 = this.data;
        loc1[loc0++] = (byte) (intValue >>> 24);
        loc1[loc0++] = (byte) (intValue >>> 16);
        loc1[loc0++] = (byte) (intValue >>> 8);
        loc1[loc0++] = (byte) intValue;
        this.length = loc0;
        return this;
    }

    private void enlarge(int increment) {
        int newLength = data.length + increment;
        data = Arrays.copyOf(data, newLength);
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.putInt(123456789);
        System.out.println(Arrays.toString(bv.data));
    }
