    private void enlarge(int size) {
        int newSize = Math.max(data.length * 2, data.length + size);
        data = Arrays.copyOf(data, newSize);
    }

    final ByteVector put11(final int byteValue1, final int byteValue2) {
        int loc0 = this.length;
        if (loc0 + 2 > data.length) {
            enlarge(2);
        }
        byte[] loc1 = this.data;
        loc1[loc0++] = (byte) byteValue1;
        loc1[loc0++] = (byte) byteValue2;
        this.length = loc0;
        return this;
    }

    public byte[] getData() {
        return Arrays.copyOf(data, length);
    }

    public int getLength() {
        return length;
    }
}

